46	{
47	    if (0 != ::close(fd))
48	    {
49	        try
50	        {
51	            throwFromErrno(
52	                    "File descriptor for \"" + std::string(filename) + "\" could not be closed. "
53	                    "Something seems to have gone wrong. Inspect errno.", ErrorCodes::CANNOT_CLOSE_FILE);
54	        }
55	        catch (const ErrnoException &)
56	        {
57	            DB::tryLogCurrentException(__PRETTY_FUNCTION__);
58	        }
59	    }
