62	MemoryStatisticsOS::Data MemoryStatisticsOS::get() const
63	{
64	    Data data;
65	
66	    constexpr size_t buf_size = 1024;
67	    char buf[buf_size];
68	
69	    ssize_t res = 0;
70	
71	    do
72	    {
73	        res = ::pread(fd, buf, buf_size, 0);
74	
75	        if (-1 == res)
76	        {
77	            if (errno == EINTR)
78	                continue;
79	
80	            throwFromErrno("Cannot read from file " + std::string(filename), ErrorCodes::CANNOT_READ_FROM_FILE_DESCRIPTOR);
81	        }
82	
83	        assert(res >= 0);
84	        break;
85	    } while (true);
86	
87	    ReadBufferFromMemory in(buf, res);
88	
89	    uint64_t unused;
90	    readIntText(data.virt, in);
91	    skipWhitespaceIfAny(in);
92	    readIntText(data.resident, in);
93	    skipWhitespaceIfAny(in);
94	    readIntText(data.shared, in);
95	    skipWhitespaceIfAny(in);
96	    readIntText(data.code, in);
97	    skipWhitespaceIfAny(in);
98	    readIntText(unused, in);
99	    skipWhitespaceIfAny(in);
100	    readIntText(data.data_and_stack, in);
101	
102	    size_t page_size = static_cast<size_t>(::getPageSize());
103	    data.virt *= page_size;
104	    data.resident *= page_size;
105	    data.shared *= page_size;
106	    data.code *= page_size;
107	    data.data_and_stack *= page_size;
108	
109	    return data;
110	}
