131	MemoryStatisticsOS::Data MemoryStatisticsOS::get() const
132	{
133	    Data data;
134	    int mib[4] = { CTL_KERN, KERN_PROC, KERN_PROC_PID, self };
135	    struct kinfo_proc kp;
136	    size_t len = sizeof(struct kinfo_proc);
137	
138	    if (-1 == ::sysctl(mib, 4, &kp, &len, NULL, 0))
139	        throwFromErrno("Cannot sysctl(kern.proc.pid." + std::to_string(self) + ")", ErrorCodes::SYSTEM_ERROR);
140	
141	    if (sizeof(struct kinfo_proc) != len)
142	        throw DB::Exception(DB::ErrorCodes::SYSTEM_ERROR, "Kernel returns structure of {} bytes instead of expected {}",
143	            len, sizeof(struct kinfo_proc));
144	
145	    if (sizeof(struct kinfo_proc) != kp.ki_structsize)
146	        throw DB::Exception(DB::ErrorCodes::SYSTEM_ERROR, "Kernel structure size ({}) does not match expected ({}).",
147	            kp.ki_structsize, sizeof(struct kinfo_proc));
148	
149	    data.virt = kp.ki_size;
150	    data.resident = kp.ki_rssize * pagesize;
151	    data.code = kp.ki_tsize * pagesize;
152	    data.data_and_stack = (kp.ki_dsize + kp.ki_ssize) * pagesize;
153	
154	    return data;
155	}
