96	int io_submit(int ctx, long nr, struct iocb * iocbpp[])
97	{
98	    for (long i = 0; i < nr; ++i)
99	    {
100	        struct aiocb * iocb = &iocbpp[i]->aio;
101	
102	        struct sigevent * se = &iocb->aio_sigevent;
103	        se->sigev_notify_kqueue = ctx;
104	        se->sigev_notify_kevent_flags = 0;
105	        se->sigev_notify = SIGEV_KEVENT;
106	        se->sigev_value.sival_ptr = iocbpp[i];
107	
108	        switch (iocb->aio_lio_opcode)
109	        {
110	            case LIO_READ:
111	            {
112	                int r = aio_read(iocb);
113	                if (r < 0)
114	                    return r;
115	                break;
116	            }
117	            case LIO_WRITE:
118	            {
119	                int r = aio_write(iocb);
120	                if (r < 0)
121	                    return r;
122	                break;
123	            }
124	        }
125	    }
126	
127	    return nr;
128	}
